import tseslint from "typescript-eslint";
import reactHooks from "eslint-plugin-react-hooks";

export default tseslint.config(
  {
    ignores: [
      "dist/**",
      "node_modules/**",
      // The playground's own build output, its Playwright script (plain
      // mjs, run by hand), its dependency tree, and the CLI-emitted demos
      // (regenerated by scripts/generate-cli-demos.mjs, never hand-edited,
      // and gated by cli's own suite). examples/src itself IS linted below.
      "examples/dist/**",
      "examples/e2e/**",
      "examples/node_modules/**",
      "examples/src/generated/**",
      // The starter template installs and builds in place (CI does, and so
      // does anyone trying it from a checkout); its source IS linted.
      "templates/*/dist/**",
      "templates/*/node_modules/**",
      // The Next.js example's build dir, dependency tree and generated env
      // declaration; its app/ source IS linted (base config: layout and
      // page must default-export for the app router).
      "examples/next/.next/**",
      "examples/next/node_modules/**",
      "examples/next/next-env.d.ts",
      "coverage/**",
      "docs/.vitepress/cache/**",
      "docs/.vitepress/dist/**",
      // Claude Code worktrees (review and fix agents check the repo out
      // under here); linting them doubles every error and is never wanted.
      ".claude/**",
      "cli/dist/**",
      "cli/tests/.tmp/**",
    ],
  },
  ...tseslint.configs.recommended,
  {
    // The playground gets the library's rule set: it is the public face of
    // the API and the hooks rules catch the same bugs there (a set-state in
    // an effect, a dependency array that changes every render).
    files: ["src/**/*.{ts,tsx}", "examples/src/**/*.{ts,tsx}"],
    plugins: { "react-hooks": reactHooks },
    rules: {
      ...reactHooks.configs.recommended.rules,
      // The library's error results and slices intentionally use readonly
      // arrays; unused vars are caught with the underscore convention.
      "@typescript-eslint/no-unused-vars": [
        "error",
        { argsIgnorePattern: "^_", varsIgnorePattern: "^_" },
      ],
    },
  },
  {
    files: ["tests/**/*.{ts,tsx}"],
    rules: {
      // Tests exercise untyped escape hatches on purpose.
      "@typescript-eslint/no-explicit-any": "off",
    },
  },
);
